import pickle, random, math
from collections import defaultdict

d4 = pickle.load(open('/tmp/dev4.pkl','rb'))
d5 = pickle.load(open('/tmp/dev5.pkl','rb'))
d6 = pickle.load(open('/tmp/dev6.pkl','rb'))
allq = pickle.load(open('/tmp/allq.pkl','rb'))
qs_all = d4+d5+d6+allq
random.seed(42)
random.shuffle(qs_all)

def build_calibration(train_qs, nbins=10):
    samples=[]
    for q in train_qs:
        for s in q['samples']:
            samples.append((s['score'], s['correct']))
    samples.sort()
    n=len(samples)
    if n < nbins*5:
        nbins = max(3, n//10)
    binsize = max(1, n//nbins)
    bins=[]
    i=0
    while i<n:
        chunk = samples[i:i+binsize] if i+binsize<=n else samples[i:]
        if len(chunk) < binsize/2 and bins:
            # merge tiny tail into last bin
            last_mid, last_frac = bins[-1]
            scores=[c[0] for c in chunk]; corr=[c[1] for c in chunk]
            bins[-1] = ((last_mid+sum(scores)/len(scores))/2, (last_frac+sum(corr)/len(corr))/2)
        else:
            scores=[c[0] for c in chunk]; corr=[c[1] for c in chunk]
            mid = sum(scores)/len(scores)
            frac = (sum(corr)+1)/(len(corr)+2)
            bins.append((mid, frac))
        i+=binsize
    return bins

def calibrate(score, bins):
    if score <= bins[0][0]:
        return bins[0][1]
    if score >= bins[-1][0]:
        return bins[-1][1]
    for i in range(len(bins)-1):
        x0,y0 = bins[i]; x1,y1 = bins[i+1]
        if x0<=score<=x1:
            if x1==x0: return y0
            t=(score-x0)/(x1-x0)
            return y0 + t*(y1-y0)
    return bins[-1][1]

def logit(p):
    p = min(max(p, 1e-4), 1-1e-4)
    return math.log(p/(1-p))

def sum_calibrated(samples, bins):
    sums=defaultdict(float)
    for s in samples:
        sums[s['answer']] += logit(calibrate(s['score'], bins))
    return max(sums.items(), key=lambda kv: kv[1])[0]

k=5
fold_size = len(qs_all)//k

for use_topic in [False, True]:
    accs=[]
    for fold in range(k):
        test_qs = qs_all[fold*fold_size:(fold+1)*fold_size]
        train_qs = qs_all[:fold*fold_size] + qs_all[(fold+1)*fold_size:]
        if use_topic:
            bins_by_topic = {}
            train_by_topic = defaultdict(list)
            for q in train_qs:
                train_by_topic[q['topic']].append(q)
            for topic, tqs in train_by_topic.items():
                bins_by_topic[topic] = build_calibration(tqs, nbins=10)
        else:
            bins_global = build_calibration(train_qs, nbins=15)
        correct=0
        for q in test_qs:
            bins = bins_by_topic[q['topic']] if use_topic else bins_global
            ans = sum_calibrated(q['samples'], bins)
            if ans==q['correct_answer']:
                correct+=1
        accs.append(correct/len(test_qs))
    print('use_topic', use_topic, 'acc', sum(accs)/len(accs))
